arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -d "limit=0" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d.get('error')); sys.exit()
for u in d['members']:
    if not u.get('is_bot'):
        real=u.get('profile',{}).get('real_name','')
        disp=u.get('real_name','')
        if 'diego' in (real+disp).lower() or 'alvarez' in (real+disp).lower():
            print(u['id'], '|', real, '|', disp)
"

